INSERT INTO rubro (id, presupuesto_id, orden, nombre, descripcion_mat, descripcion_mo, flete, equipos, subcontratos, varios, overhead_pct, margen_pct, incluir) VALUES ('p2026002luque:lq7', 'p2026002luque', 8, 'Infraestructura — media tensión hasta acometida', 'Instalación eléctrica de media tensión hasta la acometida, según proyecto aprobado por ANDE: puestos de entrega con postes de hormigón armado 12/300, 12/500 y 12/800, aisladores triple campana, pernos, crucetas poliméricas, manos francesas y cable preensamblado; excavación de zanjas con protección mecánica, caños PEAD de 4", soporterías y registros de hormigón. Incluye puestos de distribución con seccionadores fusibles y bajo carga, fusibles, barras de cobre, nichos, celdas de distribución y descargadores de sobretensión; transformadores de 100, 150 y 300 kVA, generador cabinado de 275 kVA con transferencia automática y uso de grúa; alimentación a tableros de llegada de cada medidor con cable NYY subterráneo, y gabinetes metálicos de distribución en baja tensión con sus disyuntores termomagnéticos.', NULL, 0, 0, 0, 0, 0, 0, TRUE);
