INSERT INTO rubro (id, presupuesto_id, orden, nombre, descripcion_mat, descripcion_mo, flete, equipos, subcontratos, varios, overhead_pct, margen_pct, incluir) VALUES ('p2026034tigrecasilleros:tgc9r1', 'p2026034tigrecasilleros', 1, '01 · Provisión y colocación de puertas metálicas para casilleros — 9 un', 'Provisión y colocación de 9 puertas metálicas para los casilleros existentes. Cada puerta se fabrica en chapa negra N° 18 (1,20 mm) doblada, con marco y refuerzos interiores en planchuela de 25 x 3 mm para evitar el alabeo, 3 bisagras reforzadas soldadas al cuerpo del casillero, agarradera, porta candado con tope y burlete perimetral. El trabajo comprende el relevamiento y toma de medidas de cada vano en obra, corte, doblado y armado en taller, tratamiento de la superficie con desengrasado y lijado, aplicación de fondo antióxido epoxi y dos manos de esmalte epoxi en el mismo color azul del mueble, traslado a obra, montaje, ajuste de luces y verificación del cierre de cada puerta.', NULL, 450000, 0, 0, 0, 0, 40, TRUE);
