INSERT INTO rubro (id, presupuesto_id, orden, nombre, descripcion_mat, descripcion_mo, flete, equipos, subcontratos, varios, overhead_pct, margen_pct, incluir) VALUES ('p2026035manora:lam35r1', 'p2026035manora', 1, '01 · Cambio de policarbonato en cúpula de quincho — 36,00 m²', 'Retiro del policarbonato existente y provisión y colocación de policarbonato alveolar de 8 mm con protección UV en la cúpula del quincho, superficie aproximada de 36,00 m². Comprende el desmontaje y bajada de las planchas deterioradas con retiro del material fuera del edificio, revisión y limpieza de la estructura portante con ajuste de las fijaciones flojas, colocación de las planchas nuevas respetando la cara con protección UV hacia el exterior y el sentido de los alvéolos para el escurrimiento, sellado de los cantos con cinta de aluminio en la parte superior y cinta microperforada en la inferior, perfiles H de unión entre planchas y perfiles U de cierre en los extremos, fijación con tornillos autoperforantes con arandela de neoprene EPDM, sellado perimetral con poliuretano para exterior y prueba de estanqueidad con agua.', NULL, 550000, 0, 0, 0, 0, 40, TRUE);
