INSERT INTO rubro (id, presupuesto_id, orden, nombre, descripcion_mat, descripcion_mo, flete, equipos, subcontratos, varios, overhead_pct, margen_pct, incluir) VALUES ('p2026037bahianemby:nem37r1', 'p2026037bahianemby', 1, '01 · Reposición de postes y tejido de alambre — 37,00 m', 'Reposición del cerco perimetral en los tramos con postes quebrados y tejido inexistente o destruido, longitud total 37,00 m: tramo de 32,00 m con 7 postes rotos y sin tejido, y tramo de 5,00 m con 1 poste roto y tejido totalmente deteriorado. Comprende el desmonte y limpieza de la franja de trabajo con retiro de la vegetación invasora, demolición y extracción de los postes quebrados con sus bases, excavación de pozos de 0,30 x 0,30 x 0,60 m, provisión y colocación de postes de hormigón premoldeado de 2,20 m empotrados y aplomados con hormigón, provisión y colocación de tejido de alambre romboidal galvanizado N° 12 de 1,80 m de altura con tensores, alambre de amarre y tres hilos de alambre de púa en el remate superior, tensado del tejido y retiro de los escombros y del material desmontado fuera del predio.', NULL, 450000, 0, 0, 0, 0, 40, TRUE);
