INSERT INTO rubro (id, presupuesto_id, orden, nombre, descripcion_mat, descripcion_mo, flete, equipos, subcontratos, varios, overhead_pct, margen_pct, incluir) VALUES ('p2026038nembyazulejo:nem38r1', 'p2026038nembyazulejo', 1, '01 · Colocación de azulejos en sala de tableros — 3,50 m²', 'Colocación de azulejos en la franja superior de la pared de la sala de tableros, sobre el azulejado existente, superficie aproximada de 3,50 m². Comprende el picado y retiro del revoque flojo y desprendido hasta base firme con retiro de los escombros, limpieza y humedecido del paramento, aplicación de puente de adherencia y azotada hidrófuga, ejecución del revoque de nivelación fratasado a plomo y en línea con el azulejado existente, replanteo de la junta para que coincida con la del azulejado inferior, provisión y colocación de azulejo blanco de 30 x 60 cm asentado con adhesivo cementicio para interior con llana dentada, cortes y calces en los encuentros con la cañería, el tablero y los marcos, tomado de juntas con pastina, sellado del perímetro y del encuentro con el cielorraso, protección de los tableros con film durante todo el trabajo y limpieza final del sector.', NULL, 250000, 0, 0, 0, 0, 40, TRUE);
