INSERT INTO rubro (id, presupuesto_id, orden, nombre, descripcion_mat, descripcion_mo, flete, equipos, subcontratos, varios, overhead_pct, margen_pct, incluir) VALUES ('p2026039cruzmonte:czm1', 'p2026039cruzmonte', 1, '01 · Tanque inoxidable AISI 304 · 7.000 L · Ø1.800 × h2.200 × 3 mm', 'Provisión, fabricación y montaje de un (1) tanque cilíndrico vertical en acero inoxidable AISI 304, capacidad 7.000 litros, altura 2.200 mm, diámetro 1.800 mm, espesor de chapa 3 mm, destinado a agua caliente a 45 °C para subproducto de limpieza y reposición de agua del proceso escaldador. Comprende el roleado y armado de la virola, fondo y techo cónico en chapa AISI 304 de 3 mm con soldadura TIG con aporte 308L y cordón sanitario continuo en el interior, boca de inspección Ø450 mm con tapa abisagrada, boca de venteo, bocas roscadas de 2" para entrada y rebose, brida de descarga de 3" con válvula, indicador de nivel visual, estructura de apoyo con cuatro patas en caño estructural 100 x 100 x 3 mm con placas de base y anclajes, decapado y pasivado interior, ensayo de estanqueidad con agua, flete a la planta industrial de Valenzuela, descarga con hidrogrúa, posicionamiento y aplomado sobre base provista por el cliente, y conexionado a las bocas dejadas por el cliente.', NULL, 3400000, 1300000, 0, 3841800, 0, 18, TRUE);
