BEGIN;

DROP TABLE IF EXISTS linea_mano_obra;
DROP TABLE IF EXISTS linea_material;
DROP TABLE IF EXISTS rubro;
DROP TABLE IF EXISTS presupuesto;

CREATE TABLE presupuesto (
  id              VARCHAR(60)  PRIMARY KEY,
  numero          VARCHAR(20)  NOT NULL UNIQUE,
  fecha           DATE,
  estado          VARCHAR(30),
  cliente         VARCHAR(200),
  obra            TEXT,
  domicilio       TEXT,
  contacto        VARCHAR(200),
  moneda          CHAR(3)      NOT NULL DEFAULT 'PYG',
  decimales       SMALLINT     NOT NULL DEFAULT 0,
  descuento_pct   NUMERIC(7,3) NOT NULL DEFAULT 0,
  iva_pct         NUMERIC(7,3) NOT NULL DEFAULT 0,
  total_venta     NUMERIC(16,2) NOT NULL DEFAULT 0,
  plazo           VARCHAR(120),
  validez         VARCHAR(120),
  forma_pago      VARCHAR(200),
  alcance         TEXT,
  firma_nombre    VARCHAR(120),
  firma_cargo     VARCHAR(120),
  mostrar_mo      BOOLEAN NOT NULL DEFAULT FALSE,
  mostrar_otros   BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE TABLE rubro (
  id              VARCHAR(80)  PRIMARY KEY,
  presupuesto_id  VARCHAR(60)  NOT NULL REFERENCES presupuesto(id) ON DELETE CASCADE,
  orden           SMALLINT     NOT NULL,
  nombre          TEXT,
  descripcion_mat TEXT,
  descripcion_mo  TEXT,
  flete           NUMERIC(16,2) NOT NULL DEFAULT 0,
  equipos         NUMERIC(16,2) NOT NULL DEFAULT 0,
  subcontratos    NUMERIC(16,2) NOT NULL DEFAULT 0,
  varios          NUMERIC(16,2) NOT NULL DEFAULT 0,
  overhead_pct    NUMERIC(7,3)  NOT NULL DEFAULT 0,
  margen_pct      NUMERIC(7,3)  NOT NULL DEFAULT 0,
  incluir         BOOLEAN       NOT NULL DEFAULT TRUE
);

CREATE TABLE linea_material (
  id              BIGSERIAL PRIMARY KEY,
  rubro_id        VARCHAR(80) NOT NULL REFERENCES rubro(id) ON DELETE CASCADE,
  orden           SMALLINT    NOT NULL,
  descripcion     TEXT,
  unidad          VARCHAR(20),
  cantidad        NUMERIC(16,4) NOT NULL DEFAULT 0,
  costo_unitario  NUMERIC(16,2) NOT NULL DEFAULT 0,
  desperdicio_pct NUMERIC(7,3)  NOT NULL DEFAULT 0,
  margen_pct      NUMERIC(7,3)  NOT NULL DEFAULT 0
);

CREATE TABLE linea_mano_obra (
  id              BIGSERIAL PRIMARY KEY,
  rubro_id        VARCHAR(80) NOT NULL REFERENCES rubro(id) ON DELETE CASCADE,
  orden           SMALLINT    NOT NULL,
  descripcion     TEXT,
  personas        NUMERIC(10,2) NOT NULL DEFAULT 0,
  horas           NUMERIC(10,2) NOT NULL DEFAULT 0,
  valor_hora      NUMERIC(16,2) NOT NULL DEFAULT 0,
  margen_pct      NUMERIC(7,3)  NOT NULL DEFAULT 0
);

CREATE INDEX idx_rubro_presupuesto ON rubro(presupuesto_id);
CREATE INDEX idx_mat_rubro         ON linea_material(rubro_id);
CREATE INDEX idx_mo_rubro          ON linea_mano_obra(rubro_id);
CREATE INDEX idx_presu_cliente     ON presupuesto(cliente);
CREATE INDEX idx_presu_fecha       ON presupuesto(fecha);


